/**
 * generated by stackra gen from src/config/pwa.config.ts (manifest.shareTarget, caching: preset
 * `balanced` and its route overrides, offline, push, updates, periodicSync),
 * src/config/i18n.config.ts (prefixes) and src/routes/offline/offline.route.ts (prerender) — do
 * not edit
 * Purpose: the PWA service worker: precaches the built shell, the per-locale HTML pages and the
 *          prerendered offline pages; applies the `balanced` caching preset (shell and hashed
 *          assets cache first, navigations network first with a timeout and navigation preload)
 *          with the config's per-route overrides; receives the share target's POST, keeps the
 *          payload on the device and redirects to the share page; answers a navigation it cannot
 *          reach with the app shell of the request's locale (the router then renders the route
 *          and the offline banner), and only when that shell is missing with the offline page of
 *          the same locale; wakes the outbox drain on Background Sync, receives Web Push and renews
 *          a push subscription the browser rotated.
 * Boundary: `/api/*` is NetworkOnly in every preset: tenant data never enters Cache Storage;
 *           offline data is the encrypted query persister and the outbox (ADR 0252). The health
 *           check and `/.well-known/*` always reach the network. Scope is the app origin only (ADR
 *           0255 d2). The shared payload goes to the platform's share inbox (IndexedDB), read once
 *           by the share page; it is never cached as a response. Push payloads carry a route, not
 *           content. `runtimeCacheOrigins` is empty, so no cross-origin route is registered;
 *           `periodicSync: false`, so no periodic listener is. The other presets compile to:
 *           `online-first` → every route NetworkFirst; `offline-first` → every route CacheFirst
 *           with a background refresh. Type-checked by its own program (WebWorker lib), never the
 *           renderer's.
 * Runtime: worker
 */
/// <reference lib="webworker" />
import { ExpirationPlugin } from "workbox-expiration";
import * as navigationPreload from "workbox-navigation-preload";
import {
  cleanupOutdatedCaches,
  createHandlerBoundToURL,
  matchPrecache,
  precacheAndRoute,
} from "workbox-precaching";
import { NavigationRoute, registerRoute, setCatchHandler } from "workbox-routing";
import { CacheFirst, NetworkFirst, NetworkOnly, StaleWhileRevalidate } from "workbox-strategies";
import {
  handleBackgroundSync,
  handleNotificationClick,
  handlePush,
  handlePushSubscriptionChange,
  handleShareTarget,
  handleSkipWaiting,
} from "@stackra/platform/sw";

declare const self: ServiceWorkerGlobalScope;

/**
 * Locale prefix → its app shell and its prerendered offline page (i18n.config.ts prefixes; the
 * same list as `#stackra/offline` `offlinePages`). Longest prefix first; `""` is the default.
 */
const LOCALES = [
  { prefix: "/ar-sa", shell: "/ar-sa/index.html", offline: "/ar-sa/offline" },
  { prefix: "/en-us", shell: "/en-us/index.html", offline: "/en-us/offline" },
  { prefix: "/ar", shell: "/ar/index.html", offline: "/ar/offline" },
  { prefix: "", shell: "/index.html", offline: "/offline" },
] as const;
/** Paths that always reach the network: the API, the deploy gate's check, well-known files. */
const NETWORK_ONLY = [/^\/api\//, /^\/healthz$/, /^\/\.well-known\//];
/** manifest.shareTarget.action under every locale prefix; the worker answers its POST. */
const SHARE_TARGET = /^(?:\/(?:ar-sa|en-us|ar))?\/share$/;
/** caching.maxEntries and caching.maxAge (30d) for every runtime cache. */
const expiration = () => new ExpirationPlugin({ maxEntries: 200, maxAgeSeconds: 2_592_000 });

/** The locale entry whose prefix the path starts with; the default when none does. */
function localeOf(pathname: string) {
  return (
    LOCALES.find(
      ({ prefix }) => prefix && (pathname === prefix || pathname.startsWith(`${prefix}/`)),
    ) ?? LOCALES[LOCALES.length - 1]
  );
}

precacheAndRoute(self.__WB_MANIFEST); // precacheShell: true; the HTML pages and offline pages too
cleanupOutdatedCaches();
navigationPreload.enable(); // caching.navigationPreload: true

registerRoute(({ url }) => NETWORK_ONLY.some((path) => path.test(url.pathname)), new NetworkOnly());

// manifest.shareTarget: the POST is answered here, never by the network; 303 to the share page
registerRoute(
  ({ url, request }) => request.method === "POST" && SHARE_TARGET.test(url.pathname),
  ({ event, url }) => handleShareTarget(event as FetchEvent, { redirectTo: url.pathname }),
  "POST",
);

// caching.routes overrides of the preset, same origin only
const sameOrigin = (url: URL, prefix: string) =>
  url.origin === self.location.origin && url.pathname.startsWith(prefix);
for (const [prefix, cacheName] of [
  ["/assets/", "static-assets"],
  ["/icons/", "static-icons"],
] as const) {
  // CacheStrategy.CacheFirst: hashed or versioned files
  registerRoute(
    ({ url }) => sameOrigin(url, prefix),
    new CacheFirst({ cacheName, plugins: [expiration()] }),
  );
}
// CacheStrategy.StaleWhileRevalidate: the manifest screenshots change only with a release
registerRoute(
  ({ url }) => sameOrigin(url, "/screenshots/"),
  new StaleWhileRevalidate({ cacheName: "screenshots", plugins: [expiration()] }),
);

// preset `balanced`: navigations NetworkFirst; caching.networkTimeout (3s) falls back early
registerRoute(
  new NavigationRoute(
    new NetworkFirst({ cacheName: "pages", networkTimeoutSeconds: 3, plugins: [expiration()] }),
    { denylist: NETWORK_ONLY },
  ),
);

/**
 * A navigation nothing else answered: the app shell of its locale, so the router renders the
 * route offline; only when that shell is missing, the prerendered offline page of the same locale.
 */
setCatchHandler(async (options) => {
  if (options.request.mode !== "navigate") return Response.error();
  const locale = localeOf(options.url.pathname);
  try {
    return await createHandlerBoundToURL(locale.shell)(options);
  } catch {
    return (await matchPrecache(locale.offline)) ?? Response.error();
  }
});

// offline.backgroundSync: true → drains the outbox
self.addEventListener("sync", handleBackgroundSync);
self.addEventListener("push", handlePush); // push.enabled: true; in-app elsewhere
self.addEventListener("pushsubscriptionchange", handlePushSubscriptionChange);
self.addEventListener("notificationclick", handleNotificationClick);
// updates.strategy: prompt, skipWaitingOnAccept
self.addEventListener("message", handleSkipWaiting);
